var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test case that should pass with original regex but fails with new one
    // Original: \d+(?:\.\d+)?  -> allows integers like '42'
    // New:      \d(?:\.\d+)?     -> does not allow standalone integers
    assert.strictEqual(bytes.parse('42'), 42);
    assert.strictEqual(bytes.parse('42kb'), 43008);
    assert.strictEqual(bytes.parse('42.5kb'), 43520);
    // The new regex fails on '42' because it doesn't match standalone integers
    // This is a breaking change for callers who pass integers as strings
  });
});

