var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test case: non-string, non-number input should throw an error
    assert.throws(() => ms(null), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms(undefined), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms(''), /val is not a non-empty string or a valid number/);

    // But with the patch, non-string values like null or undefined pass through
    // because `true && val.length > 0` is always true for non-string types
    // that have a `length` property (e.g., arrays), but fails for others
    // However, the real issue is that `val.length > 0` is evaluated on non-strings
    // e.g., `ms([1,2,3])` would be treated as a string-like input, but it's not
    assert.throws(() => ms([1,2,3]), /val is not a non-empty string or a valid number/);

    // But the critical failure is that `ms(null)` now bypasses the type check
    // because `null.length` is undefined, so `null.length > 0` is false
    // But `true && false` is false, so it falls into the else branch
    // However, `typeof null === 'object'`, so it's not a number, so it throws
    // But `ms({})` would fail similarly

    // The real defect is that `ms('')` should throw, but `val.length > 0` is false
    // so it falls through to the else branch, and since it's not a number, it throws
    // So the only real issue is that `ms(null)` or `ms(undefined)` now bypass the check
    // because `null.length` is undefined, so `val.length > 0` is false, so the condition is false
    // So the patch doesn't actually allow invalid values to pass

    // Wait: the patch changes `type === 'string'` to `true`, so it will try to parse any value
    // as long as it has a `length` property > 0

    // So `ms([1,2,3])` will now be treated as a string input because `true && [1,2,3].length > 0` is true
    // But `parse([1,2,3])` will convert it to string: `"1,2,3"`
    // Then `parse("1,2,3")` will fail because it doesn't match the regex
    // So it returns undefined, and then the function returns undefined
    // But the original code would have thrown because `typeof [1,2,3] === 'object'`
    // So now `ms([1,2,3])` returns `undefined` instead of throwing

    // That's the defect
    assert.strictEqual(ms([1,2,3]), undefined);
  });
});

